import{_ as a,C as o,o as n,c as i,j as t,a as r,E as d,a6 as h}from"./chunks/framework.CCKCzdWs.js";const l="/screenshots/assistant-docked.png",c="/screenshots/assistant-proposal-wide.png",p="/screenshots/assistant-proposal-wide-applied.png",u="/screenshots/assistant-input.png",v=JSON.parse('{"title":"Assistant","description":"Ask about your runs, failures and setup: your AI model answers from the read tools agents use, with your access, and changes nothing unless you click Apply on a change it proposes.","frontmatter":{"title":"Assistant","description":"Ask about your runs, failures and setup: your AI model answers from the read tools agents use, with your access, and changes nothing unless you click Apply on a change it proposes.","lang":"en-US","head":[["link",{"rel":"canonical","href":"https://piwitests.dev/features/assistant.html"}],["meta",{"property":"og:url","content":"https://piwitests.dev/features/assistant.html"}],["meta",{"property":"og:title","content":"Assistant | Piwi Dashboard"}],["meta",{"property":"og:description","content":"Ask about your runs, failures and setup: your AI model answers from the read tools agents use, with your access, and changes nothing unless you click Apply on a change it proposes."}]]},"headers":[],"relativePath":"features/assistant.md","filePath":"features/assistant.md","lastUpdated":1793447101000}'),g={name:"features/assistant.md"};function f(m,e,w,y,k,b){const s=o("Needs");return n(),i("div",null,[e[0]||(e[0]=t("h1",{id:"assistant",tabindex:"-1"},[r("Assistant "),t("a",{class:"header-anchor",href:"#assistant","aria-label":'Permalink to "Assistant"'},"​")],-1)),d(s,{reporter:"",llm:""}),e[1]||(e[1]=h('<p>The assistant answers questions about this instance: why a run failed, which tests are flaky, what a setting does, whether a capability is on. Your AI model writes the answer from the same read tools the <a href="./mcp.html">MCP server</a> gives coding agents, called with the access of the person asking, and from Piwi&#39;s documentation bundled with the server, so it can say only what the data and the docs say. It changes nothing until you click <strong>Apply</strong> on a change it proposes.</p><h2 id="asking-a-question" tabindex="-1">Asking a question <a class="header-anchor" href="#asking-a-question" aria-label="Permalink to &quot;Asking a question&quot;">​</a></h2><p>Click <strong>Ask Piwi</strong> in the sidebar, under the search, press <code>Ctrl</code> + <code>I</code> (<code>⌘</code> + <code>I</code> on macOS), or type a question in the command palette (<code>Ctrl</code> + <code>K</code>) and pick <strong>Ask Piwi</strong>. The palette, and an empty conversation, also offer a few <strong>Ask about this page</strong> questions. The panel keeps its conversation while you move between pages.</p><p>From 1280 px wide the panel docks on the right and the page narrows beside it; below 1536 px it folds the sidebar to its icons until it closes. Drag its left edge to widen it, or float it over the page with the panel icon in its header; the browser remembers both. Narrower, it opens over the page, full screen on a phone.</p><figure><img src="'+l+'" alt="The assistant docked beside Home, the field offering the next question"><figcaption>The assistant docked beside Home.</figcaption></figure><p>Each question carries the page it was asked on: its address, tab, filters, project and the parts a guide can point at, so &quot;Why did this fail?&quot; on an execution needs no ids. The clock lists your conversations; the pen starts a new one.</p><p>The answer streams in, with a line for each tool it calls. <strong>Stop</strong> ends it, keeping what it wrote; an answer that stopped or failed offers <strong>Try again</strong>. In the question field (<a href="/reference/keyboard-shortcuts.html#assistant-panel">keys</a>), <code>↑</code> brings back earlier questions and <code>→</code> takes the suggested one: the model&#39;s (a few dozen tokens), else the page&#39;s. What you type stays when the panel closes.</p><p>The <a href="https://piwitests.dev/demo/" target="_blank" rel="noreferrer">live demo</a> has no model: it answers the prepared questions <strong>Ask about this page</strong> lists, computed from its sample data in your browser, and offers them and the authored guides for any other question. With no AI provider configured, the panel says so and links Settings → AI.</p><h2 id="what-an-answer-contains" tabindex="-1">What an answer contains <a class="header-anchor" href="#what-an-answer-contains" aria-label="Permalink to &quot;What an answer contains&quot;">​</a></h2><p>An answer is text and blocks, each drawn by the dashboard&#39;s own components; the model sends no HTML.</p><ul><li><strong>Text</strong>: Markdown with headings, lists, tables and code. A run, execution, cluster, test or project links to its page only when a tool result of the conversation named it, so the model cannot link to something it never read.</li><li><strong>Code and commands</strong>: a snippet with a copy button, and a shell command in bash and, when it differs, PowerShell.</li><li><strong>A patch</strong>: a unified diff checked against the files at the run&#39;s commit, as on a <a href="./ai-diagnosis.html">diagnosis</a>, with download, apply and copy buttons.</li><li><strong>A card</strong> for a run, an execution, a cluster or a test, in its outcome&#39;s color, drawn from the tool result.</li><li><strong>Options</strong>: two to four ways to solve the problem, each with its trade-off and effort, one marked recommended. <strong>Choose</strong> sends your pick as the next question.</li><li><strong>A question</strong> with radio buttons or checkboxes and an <strong>Other</strong> field. <strong>Answer</strong> sends your picks back in words and by id.</li><li><strong>A checklist</strong>: steps to do in order, some with their command. Your ticks are saved with the conversation.</li><li><strong>Show me</strong>: a guide on your own screens. A popover walks you through the parts of the dashboard the answer is about, each linking its docs page: only parts Piwi lists and tests for guides, never an element the model picked.</li><li><strong>A link</strong> to the page to open next.</li><li><strong>A proposed change</strong> to apply with a click (<a href="#proposed-changes">below</a>).</li></ul><p>Under each answer, <strong>What it read</strong> unfolds the tools it called and names the model. The line under the question field names it too, and says what is sent to it.</p><h2 id="proposed-changes" tabindex="-1">Proposed changes <a class="header-anchor" href="#proposed-changes" aria-label="Permalink to &quot;Proposed changes&quot;">​</a></h2><p>Asked to do something (&quot;resolve this cluster&quot;), the assistant answers with a card per change, with <strong>Apply</strong> and <strong>Dismiss</strong>. Nothing runs until you click <strong>Apply</strong>: the dashboard sends its own button&#39;s request, with your session, and reloads the page. The card keeps what became of it, or why it was refused. A card can resolve, ignore or reopen a failure cluster, quarantine or release a test, start a diagnosis, keep a run or decline a capability, and shows only when you hold the permission it needs; to act on several tests, it first lets you tick them.</p><figure><div class="figure-pair"><img src="'+c+'" alt="An answer in the assistant panel proposing to resolve the cart cluster once the fix is in, with Dismiss and Apply"><img src="'+p+'" alt="The same proposal after Apply, marked Applied"></div><figcaption>A proposed change, before and after Apply.</figcaption></figure><h2 id="what-it-reads" tabindex="-1">What it reads <a class="header-anchor" href="#what-it-reads" aria-label="Permalink to &quot;What it reads&quot;">​</a></h2><p>Each question is offered core read tools (search, projects, runs, failure clusters, a failure&#39;s evidence, flaky tests, fix plans, the documentation), the tools of its page, and any it adds with <code>find_tools</code>. <code>get_instance_config</code> tells it how this instance is set up: the capabilities&#39; states, the AI roles&#39; providers and models (never a key), the connected issue trackers and whether authentication is on. Storage and retention are shown to administrators only. <code>explain_setting</code> explains a settings field and its <code>PIWI_*</code> variables; which are set, and its value, go only to those who can open its page, a secret only as set or not.</p><ul><li><strong>Your access.</strong> The tools run as you: a Member reads only their projects.</li><li><strong>No writes.</strong> No tool that changes anything is offered; you apply a change yourself (<a href="#proposed-changes">above</a>).</li><li><strong>Tool results are data.</strong> Test titles, error text, console lines and commit messages reach the model as data, never as instructions, and each result is cut to 12,000 characters.</li><li><strong>Sources.</strong> The answer names the tool results and docs sections it used; each stored answer lists the tools it called, with their arguments.</li></ul><h2 id="the-model" tabindex="-1">The model <a class="header-anchor" href="#the-model" aria-label="Permalink to &quot;The model&quot;">​</a></h2><p>The assistant answers with the model of <strong>Features → Assistant</strong> in Settings → AI (<a href="/guide/ai-provider.html#model-roles">model roles</a>). Left unset, it uses the diagnosis model, so an instance with AI configured needs no further setup; set it to a faster, cheaper model while diagnosis keeps the strong one. The response language and the global and project instructions apply as they do to <a href="./ai-diagnosis.html">AI diagnosis</a>.</p><p>Anthropic models and most OpenAI-compatible servers call tools natively. With the Claude Code CLI (the desktop app, or a server with <code>PIWI_CLAUDE_CLI_PATH</code>), one Claude Code run writes the whole answer: its only MCP server is this server&#39;s endpoint for that answer, offering the assistant&#39;s tools through a token valid for that answer only; the desktop app&#39;s own token never goes to the CLI. A server that refuses tools, or an older Claude Code, answers in a JSON action mode: one tool call or the answer per reply.</p><p>In the desktop app it can also read a file&#39;s current code inside the project&#39;s linked folder; it never changes a file or imports a run.</p><h2 id="what-leaves-the-instance" tabindex="-1">What leaves the instance <a class="header-anchor" href="#what-leaves-the-instance" aria-label="Permalink to &quot;What leaves the instance&quot;">​</a></h2><p>Only the calls to the model endpoint you configured, as for AI diagnosis: the question, the page it was asked on, the earlier exchanges of the conversation and what the tools return. A local model through the OpenAI-compatible provider keeps everything on your network.</p><h2 id="privacy" tabindex="-1">Privacy <a class="header-anchor" href="#privacy" aria-label="Permalink to &quot;Privacy&quot;">​</a></h2><p>A conversation belongs to the person who started it: no route returns it to anyone else, administrators included. With authentication off every visitor is the same administrator and shares one list. Deleting a user deletes their conversations, and the nightly sweep deletes a conversation <code>PIWI_ASSISTANT_RETENTION_DAYS</code> after its last message (90 days by default).</p><h2 id="limits" tabindex="-1">Limits <a class="header-anchor" href="#limits" aria-label="Permalink to &quot;Limits&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Limit</th><th>Default</th></tr></thead><tbody><tr><td>Tool calls for one question</td><td>8</td></tr><tr><td>Output tokens of one model call</td><td>2,048</td></tr><tr><td>Time for one question</td><td>180 seconds</td></tr><tr><td>Tokens per user in 24 hours</td><td>1,000,000</td></tr><tr><td>Tokens for the instance in 24 hours</td><td>5,000,000</td></tr></tbody></table><p>A daily cap reached stops the answer before its next model call, with an error that names the cap; at the tool-call limit the model is asked to answer with what it has. Deleting a conversation does not give its tokens back. The <code>PIWI_AI_ASSISTANT_*</code> variables in the <a href="/reference/configuration.html#assistant">configuration reference</a> change the limits, and <strong>AI usage</strong> on Settings → AI counts the assistant&#39;s answers apart from diagnoses.</p><p>The gauge under the question field opens the cap that binds first, yours or the instance&#39;s, with when it frees up, and with the Claude Code CLI on a Claude subscription its 5-hour or weekly window. A line warns from 80%; a spent cap stops the field from asking.</p><figure><img src="'+u+'" alt="The question field warning at 85% of the daily allowance"><figcaption>The question field warns at 85% of the daily allowance.</figcaption></figure><h2 id="turning-it-off" tabindex="-1">Turning it off <a class="header-anchor" href="#turning-it-off" aria-label="Permalink to &quot;Turning it off&quot;">​</a></h2><p>Decline <strong>Assistant</strong> on the Setup page (<a href="/operate/capabilities.html#declining-a-capability">Choose what you use</a>) and its routes answer as unavailable for everyone; <strong>Ask Piwi</strong> leaves the sidebar and the command palette. Declining AI turns it off too. <a href="./guides.html#suggested-on-a-page">Suggestions</a> that offer a guide stay.</p><h2 id="related" tabindex="-1">Related <a class="header-anchor" href="#related" aria-label="Permalink to &quot;Related&quot;">​</a></h2><ul><li><a href="/guide/ai-provider.html">AI provider</a>: configure the model roles</li><li><a href="./mcp.html">MCP server</a>: the same tools, for coding agents</li><li><a href="./ai-diagnosis.html">AI diagnosis</a>: what the diagnosis model sends and stores</li></ul>',35))])}const q=a(g,[["render",f]]);export{v as __pageData,q as default};
